package com.megathon.incidentassistant.ai

import android.content.Context
import java.io.File

/**
 * Locates and validates the Whisper model directory.
 *
 * `Whisper.init(String path)` (see `Whisper.java`, `init(int mode, String path)`) lists the
 * directory and auto-detects these three files:
 *
 *   - `vocab.bin`                 (generated by notebook/whisper/npu/whisper_vocab)
 *   - `encoder_model_htp.bin`     (from AI Hub, runtime "Qualcomm AI Runtime")
 *   - `decoder_model_htp.bin`     (from AI Hub)
 *
 * It also passes `path` as the CDSP path, which is appended to `DSP_LIBRARY_PATH`, so the
 * device-side `libQnnHtpVxxSkel.so` must sit in the same directory.
 *
 * Two locations are checked, in order:
 *   1. `<app.getExternalFilesDir>/whisper` - writable by `adb push` without root.
 *   2. `/vendor/etc/whisper` - the path used by Qualcomm's own sample app; requires
 *      `adb root && adb remount`.
 */
object WhisperModels {

    const val VENDOR_DIR = "/vendor/etc/whisper"
    private val REQUIRED = listOf("vocab.bin", "encoder_model_htp.bin", "decoder_model_htp.bin")

    /** Preferred on-device directory for app-private installs (no root needed). */
    fun appDir(context: Context): String? =
        context.getExternalFilesDir(null)?.let { File(it, "whisper").absolutePath }

    fun looksComplete(dir: String): Boolean {
        val f = File(dir)
        if (!f.isDirectory) return false
        return REQUIRED.all { File(f, it).exists() }
    }

    /** First directory that has all three model files, or null if models are absent. */
    fun resolve(context: Context): String? {
        val local = appDir(context)
        if (local != null && looksComplete(local)) return local
        if (looksComplete(VENDOR_DIR)) return VENDOR_DIR
        return null
    }

    /** Files present but incomplete - useful for a precise error message. */
    fun describe(dir: String): String {
        val f = File(dir)
        if (!f.isDirectory) return "$dir (not a directory)"
        val present = REQUIRED.count { File(f, it).exists() }
        val missing = REQUIRED.filter { !File(f, it).exists() }
        return buildString {
            append("$dir: $present/${REQUIRED.size} model files")
            if (missing.isNotEmpty()) append(" missing=").append(missing.joinToString(","))
        }
    }
}

/** Cheap check used by [com.megathon.incidentassistant.AppContainer] at start-up. */
object WhisperModelsAvailable {
    fun check(context: Context): Boolean = WhisperModels.resolve(context) != null
}
